def reachable_within(src, target, steps, used, current_pos):
    # Can reach target in exactly steps moves using unvisited nodes plus target, not considering fixed positions before target? rough BFS with parity/dist
    # use shortest distance in graph avoiding used (target allowed)
    if steps<0: return False
    frontier={src}
    seen={src}
    for d in range(steps):
        nf=set()
        for u in frontier:
            for w in adj[u]:
                if w==target or (not used[w] and (w not in fixed_val_to_pos or fixed_val_to_pos[w] >= current_pos+d+1)):
                    # don't step on future fixed values before their positions? if fixed pos > arrival possibly maybe can only at exact pos
                    nf.add(w)
        frontier=nf
        if not frontier: return False
    return target in frontier

def check_future(pos, cur):
    # for each next fixed position q>pos, target fixed[q], ensure rough shortest and parity maybe exactly possible ignoring most constraints
    # at least adjacency if q=pos+1
    lastp=pos; lastv=cur
    for q in sorted(p for p in fixed if p>pos):
        target=fixed[q]
        steps=q-lastp
        # Shortest distance avoiding used, with fixed values unavailable except target maybe
        # simple BFS shortest <= steps and same color parity? Knight alternates color, board bipartite color parity = (r+c)%2.
        if ((lastv//N+lastv%N) + steps) %2 != (target//N+target%N)%2:
            return False
        # BFS for min distance using unvisited plus target
        front={lastv}; seen={lastv}; dist=None
        for d in range(steps+1):
            if target in front:
                dist=d; break
            nf=set()
            for u in front:
                for w in adj[u]:
                    if w==target or (not used[w] and w not in fixed_val_to_pos): # cannot use future fixed values as intermediates
                        if w not in seen:
                            seen.add(w); nf.add(w)
            front=nf
        if dist is None or dist>steps: return False
        lastp=q; lastv=target
    return True

