def dfs(pos):
    global nodes
    nodes+=1
    if nodes%1000000==0:
        print('nodes',nodes,'pos',pos,'time',time.time()-start,'prefix',path[:pos+1], flush=True)
    if pos==V-1:
        return True
    cur=path[pos]
    np=pos+1
    if np in fixed:
        cand=[fixed[np]]
    else:
        cand=[w for w in adj[cur] if not used[w] and w not in fixed_val_to_pos]
        # if a candidate would make next fixed impossible by not adjacent if q=np+1? order warnsdorff
        def score(w):
            # degree of onward candidates at next pos, lower first; also closeness to next fixed
            deg=0
            nnp=np+1
            for z in adj[w]:
                if not used[z] and z!=w:
                    if nnp in fixed:
                        if z==fixed[nnp]: deg+=1
                    else:
                        if z not in fixed_val_to_pos: deg+=1
            # distance to next fixed target
            return deg
        cand.sort(key=score)
    for w in cand:
        if used[w]: continue
        # cannot use fixed value at wrong position
        if w in fixed_val_to_pos and fixed_val_to_pos[w]!=np: continue
        if w not in adj[cur]: continue
        path[np]=w; used[w]=True
        if check_future(np,w):
            if dfs(np): return True
        used[w]=False; path[np]=None if np not in fixed else path[np]
    return False

